# create a new database
CREATE DATABASE healthpluscare_db;

# using the created db
USE healthpluscare_db;

# clinics table creation
CREATE TABLE Clinics (
clinic_id VARCHAR(6) NOT NULL,
clinic_name VARCHAR(100) NOT NULL,
clinic_type VARCHAR(50) NOT NULL,
city VARCHAR(50) NOT NULL,
state VARCHAR(30) NOT NULL,
established_year INT(6) NOT NULL,
contact_number VARCHAR(20) NOT NULL,
CONSTRAINT pk_Clinics PRIMARY KEY(clinic_id) 
);

# inserting values into Clinics table

# specialists table creation
CREATE TABLE Specialists (
specialist_id VARCHAR(8) NOT NULL,
first_name VARCHAR(15) NOT NULL,
last_name VARCHAR(15) NOT NULL,
gender VARCHAR(8) NOT NULL,
specialization VARCHAR(50) NOT NULL,
clinic_id VARCHAR(6) NOT NULL,
qualification VARCHAR(20) NOT NULL,
experience_years INT(4) NOT NULL,
consultation_fee DECIMAL(8,2) NOT NULL,
CONSTRAINT pk_Specialists PRIMARY KEY(specialist_id),
CONSTRAINT fk_Specialists_Clinics FOREIGN KEY(clinic_id) REFERENCES Clinics(clinic_id)
);

# inserting values into Specialists table

# Members table creation
CREATE TABLE Members (
member_id VARCHAR(10) NOT NULL,
first_name VARCHAR(15) NOT NULL,
last_name VARCHAR(15) NOT NULL,
gender VARCHAR(8) NOT NULL,
date_of_birth VARCHAR(15) NOT NULL,
age INT NOT NULL,
city VARCHAR(50) NOT NULL,
membership_type VARCHAR(30) NOT NULL,
registration_date VARCHAR(15) NOT NULL,
phone_number VARCHAR(15) NULL,
email VARCHAR(100) NULL,
CONSTRAINT pk_Members PRIMARY KEY(member_id)
);

# inserting values into Members table

# Corporates table creation
CREATE TABLE Corporates (
corporate_id VARCHAR(10) NOT NULL,
company_name VARCHAR(50) NOT NULL,
industry VARCHAR(50) NOT NULL,
city VARCHAR(50) NOT NULL,
contract_start_date VARCHAR(15) NOT NULL,
contract_end_date VARCHAR(15) NOT NULL,
employee_count INT NOT NULL,
CONSTRAINT pk_Corporates PRIMARY KEY(corporate_id)
);

# inserting values into Corporates table

# Corporates_Members table creation
CREATE TABLE Corporate_Members (
corporate_member_id VARCHAR(10) NOT NULL,
corporate_id VARCHAR(10) NOT NULL,
member_id VARCHAR(10) NOT NULL,
designation VARCHAR(30) NOT NULL,
enrollment_date VARCHAR(15) NOT NULL,
CONSTRAINT pk_Corporate_Members PRIMARY KEY(corporate_member_id),
CONSTRAINT fk_Corporate_Members_Corporate FOREIGN KEY(corporate_id)  REFERENCES Corporates(corporate_id),
CONSTRAINT fk_Corporate_Members_Members FOREIGN KEY(member_id) REFERENCES Members(member_id)
);

# inserting values into Corporate_Members table

# Consultation table creation
CREATE TABLE Consultations (
consultation_id VARCHAR(10) NOT NULL,
member_id VARCHAR(10) NOT NULL,
specialist_id VARCHAR(10) NOT NULL,
clinic_id VARCHAR(6) NOT NULL,
consultation_date VARCHAR(15) NOT NULL,
consultation_mode VARCHAR(30) NOT NULL,
status VARCHAR(20) NOT NULL,
reason_for_visit VARCHAR(50) NOT NULL,
CONSTRAINT pk_Consultations PRIMARY KEY(consultation_id),
CONSTRAINT fk_Consultations_Members FOREIGN KEY(member_id) REFERENCES Members(member_id),
CONSTRAINT fk_Consultations_Specialists FOREIGN KEY(specialist_id) REFERENCES Specialists(specialist_id),
CONSTRAINT fk_Consultations_Clinics FOREIGN KEY(clinic_id) REFERENCES Clinics(clinic_id)
);

# inserting values into Consultations table

# Telemedicines_Sessions table creation
CREATE TABLE Telemedicine_Sessions (
session_id VARCHAR(10) NOT NULL,
consultation_id VARCHAR(10) NOT NULL,
session_start_time DATETIME NOT NULL,
session_end_time DATETIME NOT NULL,
platform VARCHAR(20) NOT NULL,
connection_quality VARCHAR(20) NOT NULL,
session_status VARCHAR(15) NOT NULL,
CONSTRAINT pk_Telemedicines_Sessions PRIMARY KEY(session_id),
CONSTRAINT fk_Telemedicines_Sessions FOREIGN KEY(consultation_id) REFERENCES Consultations(consultation_id)
);

# inserting values into Telemedicines_Sessions

# Chronic_Care table creation
CREATE TABLE Chronic_Care_Programs (
program_id VARCHAR(10) NOT NULL,
member_id VARCHAR(10) NOT NULL,
specialist_id VARCHAR(10) NOT NULL,
condition_name VARCHAR(60) NOT NULL,
enrollment_date VARCHAR(15) NOT NULL,
program_status VARCHAR(30) NOT NULL,
next_review_date VARCHAR(15) NOT NULL,
CONSTRAINT pk_Chronic_Care_Programs PRIMARY KEY(program_id),
CONSTRAINT fk_Chronic_Care_Programs_Members FOREIGN KEY(member_id) REFERENCES Members(member_id),
CONSTRAINT fk_Chronic_Care_Programs_Specialists FOREIGN KEY(specialist_id) REFERENCES Specialists(specialist_id)
);

# inserting values into Chronic_Care_Programs Table

# Health_Packages Table Creation
CREATE TABLE Health_Packages (
package_id VARCHAR(8) NOT NULL,
package_name VARCHAR(100) NOT NULL,
package_type VARCHAR(20) NOT NULL,
price INT NOT NULL,
validity_days INT NOT NULL,
tests_included INT NOT NULL,
CONSTRAINT pk_Health_Packages PRIMARY KEY(package_id)
);

# inserting values into Health_Packages Table

# Package_Subscriptions table creation
CREATE TABLE Package_Subscriptions (
subscription_id VARCHAR(10) NOT NULL,
member_id VARCHAR(10) NOT NULL,
package_id VARCHAR(8) NOT NULL,
subscription_date VARCHAR(15) NOT NULL,
expiry_date VARCHAR(15) NOT NULL,
payment_status VARCHAR(15) NOT NULL,
CONSTRAINT pk_Package_Subscriptions PRIMARY KEY(subscription_id),
CONSTRAINT fk_Package_Subscriptions_Members FOREIGN KEY(member_id) REFERENCES Members(member_id),
CONSTRAINT fk_Package_Subscriptions_Health_Packages FOREIGN KEY(package_id) REFERENCES Health_Packages(package_id)
);

# inserting values into Package_Subscriptions Table

# Prescriptions table creation
CREATE TABLE Prescriptions (
prescription_id VARCHAR(10) NOT NULL,
consultation_id VARCHAR(10) NOT NULL,
member_id VARCHAR(10) NOT NULL,
specialist_id VARCHAR(10) NOT NULL,
medicine_name VARCHAR(50) NOT NULL,
dosage VARCHAR(20) NOT NULL,
duration_days INT NOT NULL,
prescribed_date VARCHAR(15) NOT NULL,
CONSTRAINT pk_prescription_id PRIMARY KEY(prescription_id),
CONSTRAINT fk_Prescriptions_Consultations FOREIGN KEY(consultation_id) REFERENCES Consultations(consultation_id),
CONSTRAINT fk_Prescriptions_Members FOREIGN KEY(member_id) REFERENCES Members(member_id),
CONSTRAINT fk_Prescriptions_Specialists FOREIGN KEY(Specialist_id) REFERENCES Specialists(specialist_id)
);

# inserting values into Prescriptions table

# Lab_Tests table creation
CREATE TABLE Lab_Tests (
lab_test_id VARCHAR(10) NOT NULL,
member_id VARCHAR(10) NOT NULL,
clinic_id VARCHAR(6) NOT NULL,
test_name VARCHAR(50) NOT NULL,
test_date VARCHAR(15) NOT NULL,
test_result VARCHAR(15) NOT NULL,
test_cost DECIMAL(8,2) NOT NULL,
test_status VARCHAR(15) NOT NULL,
CONSTRAINT pk_Lab_Tests PRIMARY KEY(lab_test_id),
CONSTRAINT fk_Lab_Tests_Members FOREIGN KEY(member_id) REFERENCES Members(member_id),
CONSTRAINT fk_Lab_Tests_Clinics FOREIGN KEY(clinic_id) REFERENCES Clinics(clinic_id)
);

# inserting values into Lab_Tests table

# Claims table creation
CREATE TABLE Claims (
claim_id VARCHAR(10) NOT NULL,
member_id VARCHAR(10) NOT NULL,
consultation_id VARCHAR(10) NULL,
claim_amount DECIMAL(8,2) NOT NULL,
claim_date VARCHAR(15) NOT NULL,
claim_status VARCHAR(15) NOT NULL,
insurance_provider VARCHAR(100) NOT NULL,
CONSTRAINT pk_Claims PRIMARY KEY(claim_id),
CONSTRAINT fk_Claims_Members FOREIGN KEY(member_id) REFERENCES Members(member_id),
CONSTRAINT fk_Claims_Consultations FOREIGN KEY(consultation_id) REFERENCES Consultations(Consultation_id)
);

# consult_id and insurance provider turned into not null to null
ALTER TABLE Claims 
MODIFY COLUMN consultation_id VARCHAR(10) NULL;
ALTER TABLE Claims
MODIFY COLUMN insurance_provider VARCHAR(100) NULL;

